mapper.select:
SELECT * FROM TB_QNA
WHERE USERNAME = #{username}
ORDER BY REG_DATE DESC

SELECT Q.QNA_SEQ , Q.USER_SEQ , Q.USERNAME , Q.PRODUCT_SEQ , Q.QUESTION , Q.ANSWER , IFNULL(Q.IS_SECRET,0) AS IS_SECRET , Q.REG_DATE , Q.UPD_DATE , P.NAME AS PRODUCT_NAME FROM TB_QNA Q INNER JOIN TB_PRODUCT P ON Q.PRODUCT_SEQ = P.PRODUCT_SEQ WHERE Q.PRODUCT_SEQ = #{productSeq} ORDER BY Q.REG_DATE DESC
LIMIT #{limit}
OFFSET #{offset}

mapper.insert:
INSERT INTO TB_QNA ( PRODUCT_SEQ
    , USER_SEQ
    , USERNAME
    , QUESTION
    , IS_SECRET
    , REG_DATE)
VALUES ( #{productSeq}
    , #{userSeq}
    , #{username}
    , #{question}
    , #{isSecret}
    , NOW())

mapper.update:
UPDATE TB_QNA
SET QUESTION = #{question}
    , ANSWER = #{answer}
    , IS_SECRET = #{isSecret}
    , UPD_DATE = NOW()
WHERE QNA_SEQ = #{qnaSeq}
    AND USERNAME = #{username}

mapper.delete:
DELETE FROM TB_QNA
WHERE QNA_SEQ = #{qnaSeq}
    AND USERNAME = #{username}
